def comprimir_repeticiones(texto: str) -> str:
    if not texto:
        return ""

    resultado = []
    contador = 1

    for i in range(1, len(texto)):
        if texto[i] == texto[i-1]:
            contador += 1
        else:
            resultado.append(texto[i-1] + str(contador))
            contador = 1

    # Agregar el último grupo
    resultado.append(texto[-1] + str(contador))

    return "".join(resultado)

def iniciales(nombre: str) -> str:
    # Split by any whitespace (handles spaces, tabs, newlines)
    palabras = nombre.split()
    # Take first character of each word and convert to uppercase
    return ''.join(palabra[0].upper() for palabra in palabras)

def aplanar(datos: list) -> list:
    resultado = []
    for elemento in datos:
        if isinstance(elemento, (list, tuple)):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado

import csv

def parsear_ventas(texto: str) -> list[dict]:
    # Split into lines and filter out empty/whitespace-only lines
    lines = texto.splitlines()
    non_empty_lines = [line for line in lines if line.strip()]

    if not non_empty_lines:
        return []

    # Check header is exactly "fecha,producto,cantidad,precio"
    expected_header = "fecha,producto,cantidad,precio"
    if non_empty_lines[0].strip() != expected_header:
        raise ValueError("La cabecera no es la indicada")

    # Parse remaining rows using csv module to handle quoted fields correctly
    reader = csv.reader(non_empty_lines[1:], delimiter=',')
    result = []

    for row in reader:
        if len(row) != 4:
            raise ValueError("Una fila no tiene exactamente 4 campos")

        fecha, producto, cantidad_str, precio_str = row

        # Validate and convert cantidad
        try:
            cantidad = int(cantidad_str)
        except ValueError:
            raise ValueError("cantidad no es un entero")

        if cantidad < 0:
            raise ValueError("cantidad es negativa")

        # Validate and convert precio
        try:
            precio = float(precio_str)
        except ValueError:
            raise ValueError("precio no es un número")

        result.append({
            "fecha": fecha,
            "producto": producto,
            "cantidad": cantidad,
            "precio": precio
        })

    return result

from datetime import datetime

def parsear_fecha(texto: str) -> str:
    # Remove leading/trailing whitespace
    texto = texto.strip()

    # Try format 1: AAAA-MM-DD
    try:
        dt = datetime.strptime(texto, "%Y-%m-%d")
        return dt.strftime("%Y-%m-%d")
    except ValueError:
        pass

    # Try format 2: DD/MM/AAAA
    try:
        dt = datetime.strptime(texto, "%d/%m/%Y")
        return dt.strftime("%Y-%m-%d")
    except ValueError:
        pass

    # Try format 3: D de MES de AAAA
    parts = texto.split()
    if len(parts) != 5:
        raise ValueError("Formato no reconocido")

    day_str, de1, month_name, de2, year_str = parts

    # Validate numeric fields
    if not (day_str.isdigit() and year_str.isdigit()):
        raise ValueError("Día y año deben ser números")

    try:
        day = int(day_str)
        year = int(year_str)
    except ValueError:
        raise ValueError("Día y año deben ser números")

    # Validate month name (case-insensitive)
    months_es = {
        "enero": 1, "febrero": 2, "marzo": 3, "abril": 4,
        "mayo": 5, "junio": 6, "julio": 7, "agosto": 8,
        "septiembre": 9, "octubre": 10, "noviembre": 11, "diciembre": 12
    }

    if month_name.lower() not in months_es:
        raise ValueError("Mes inválido")

    month = months_es[month_name.lower()]

    # Create and validate the date (handles leap years automatically)
    try:
        dt = datetime(day, month, year)
    except ValueError as e:
        raise ValueError("Fecha inválida") from e

    return dt.strftime("%Y-%m-%d")

def promedio_movil(valores: list[float], ventura: int) -> list[float]:
    if ventura <= 0 or ventura > len(valores):
        return []
    resultado = []
    for i in range(len(valores) - ventura + 1):
        resultado.append(sum(valores[i:i + ventura]) / ventura)
    return resultado

from collections import OrderedDict


class CacheLRU:
    def __init__(self, capacidad: int):
        if capacidad < 0:
            raise ValueError("La capacidad debe ser un entero no negativo")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave not in self._datos:
            return None
        # Mover a fondo para marcar como usado recientemente
        self._datos.move_to_end(clave)
        return self._datos[clave]

    def put(self, clave, valor):
        # Si la capacidad es 0, no guardamos nada (no hay espacio)
        if self.capacidad == 0:
            return

        # Si la clave no existe y la caché está llena, descartar el más antiguo
        if clave not in self._datos and len(self._datos) >= self.capacidad:
            self._datos.popitem(last=False)

        self._datos[clave] = valor

    def __len__(self):
        return len(self._datos)
